window.STORY_CHAPTERS["c23f0f788e79c6fba"]={"id":"c23f0f788e79c6fba","lines":[{"uid":"talk.vc.home_time_yuriko_alo_3#originalText","id":"talk.vc.home_time_yuriko_alo_3","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"就算在游戏世界中，朝阳果然还是一样刺眼。不过感觉很舒服呢。","en":"I can't get over how bright the morning sun is in this game. I like it, though.","ja":"ゲームの中でも、やっぱり朝日はまぶしいんですねでも、いい気持ちです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuriko_alo_4#originalText","id":"talk.vc.home_time_yuriko_alo_4","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"有好多妖精模样的人走在街上，很有幻想世界的感觉呢！","en":"Seeing all those fairies walking around town is just so magical!","ja":"妖精の格好をした人たちがたくさん街を歩いているのってなんだか幻想的です!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuriko_alo_5#originalText","id":"talk.vc.home_time_yuriko_alo_5","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"游戏中也可以吃饭耶！明明是VR世界却能尝到味道……真不得了！","en":"I love that we get to eat in this game! I'm amazed at how good VR food actually tastes.","ja":"ゲーム中にご飯も食べられるんですね! VRなのに味がするのって……すごいです!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuriko_alo_6#originalText","id":"talk.vc.home_time_yuriko_alo_6","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"要是能和小杏一起攻略这个游戏，一定会非常有趣……","en":"If I could beat this game with Anna... Ohhh, that would be so much fun!","ja":"杏奈ちゃんと一緒にこのゲームを攻略したら、きっととっても楽しいだろうなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuriko_alo_7#originalText","id":"talk.vc.home_time_yuriko_alo_7","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"幻想世界中的夜晚森林……真没想到会有亲眼见识到的一天。","en":"I never thought I'd be in a dark forest of a fantasy world, but here I am.","ja":"ファンタジー世界の、夜の森……まさか、この目で見られるとは思っていなかったです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuriko_alo_8#originalText","id":"talk.vc.home_time_yuriko_alo_8","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"这里的夜晚果然跟现实完全不同！真的是一片漆黑，有点恐怖。","en":"Night here is completely different from in the real world. It truly is pitch-black. It's actually kinda scary.","ja":"やっぱり、現実の夜とは全然違いますね本当に真っ暗で、ちょっと怖いです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuriko_alo_9#originalText","id":"talk.vc.home_time_yuriko_alo_9","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"现实已经是晚上了吧。游戏里还很明亮，让人不禁觉得还能继续玩下去。","en":"It's already bedtime in the real world. But it's still light here. I feel like I could keep playing.","ja":"現実では、もう夜なんですねこっちはまだ明るくてまだまだ遊べそうな気がしちゃいます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuriko_alo_10#originalText","id":"talk.vc.home_time_yuriko_alo_10","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"果然，不会产生「在游戏中熬夜」的感觉。是如此接近现实呀……","en":"Everything feels so real, it could be midnight and it'd still feel like noon.","ja":"やっぱり、「ゲームで夜更かし」っていう感覚にならないですねそれだけリアルに近いんだなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuriko_alo_11#originalText","id":"talk.vc.home_time_yuriko_alo_11","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"已经这么晚了，你还醒着啊？呵呵，和我一样呢。","en":"You're still up? Haha, guess that makes two of us.","ja":"こんな時間なのにまだ起きてるんですか?ふふ、私と一緒ですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_yuriko_alo_12#originalText","id":"talk.vc.home_time_yuriko_alo_12","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"那个……我有点睡不着，可以陪我说说话吗？","en":"Hey...I'm having a hard time sleeping. Can we talk for a little while?","ja":"あの……なんだか眠れなくて少しだけ、おしゃべりに付き合ってもらってもいいですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuriko_alo_1#originalText","id":"talk.vc.home_day_yuriko_alo_1","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"今天是星期一，但游戏里还是有不少人上线的样子。可见玩游戏真的很开心呢！","en":"There seems to be a lot of people here for a Monday. That just goes to show how much fun this game is!","ja":"月曜日だけど、ゲームの中にかなりの人がいるみたいですそれだけ楽しいってことですね!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuriko_alo_2#originalText","id":"talk.vc.home_day_yuriko_alo_2","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"要是这个世界里有学校，肯定很轻松。因为可以用飞的去上学。","en":"School would be fun in this world. Who doesn't love commuting by air?","ja":"この世界に学校があったらきっと楽ですよね空を飛んで登校できますから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuriko_alo_3#originalText","id":"talk.vc.home_day_yuriko_alo_3","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"放假的时候我想去书店……不知道这个世界是不是也有书店呢？","en":"I was planning on spending my day off at the bookstore. Do you think this world has one?","ja":"お休みの日は、本屋さんに行こうと思ったんですけど……この世界にもあるんでしょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuriko_alo_4#originalText","id":"talk.vc.home_day_yuriko_alo_4","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"这个礼拜也辛苦了！下礼拜再一起好好努力吧！","en":"Another week starts tomorrow. Let's crush it together again!","ja":"今週もお疲れさまでしたまた来週から、一緒に頑張りましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_1#originalText","id":"talk.vc.home_event_yuriko_alo_1","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"新年快乐。今年也要一起开心度过一整年唷！","en":"Happy New Year! Let's make it a good one together!","ja":"あけましておめでとうございます今年も一年、一緒に楽しい年にしていきましょうねっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_2#originalText","id":"talk.vc.home_event_yuriko_alo_2","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"在游戏里撒豆子的话，鬼是不是会跑到游戏外面呢？","en":"When you throw Setsubun beans in-game, does that send the demons \"outside\" into the real world?","ja":"ゲームの中で豆をまいたら鬼はゲームの外に出て行ってしまうんでしょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_3#originalText","id":"talk.vc.home_event_yuriko_alo_3","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"那、那个！这是情人节的……请、请收下！","en":"W-Wait, sir! Here... A Valentine. I-It's for you!","ja":"あ、あのっ!これ……バレンタインの……う、受け取ってください!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_4#originalText","id":"talk.vc.home_event_yuriko_alo_4","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"从小我就很向往女儿节童谣里出现的小米酒，当时我一直认为那肯定非常美味。","en":"You know the white sake in the Hinamatsuri song? I wanted to drink it so bad when I was a kid.","ja":"おひな様の歌に出てくる白酒小さい頃は憧れました。きっとすごくおいしいんだろうなって"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_5#originalText","id":"talk.vc.home_event_yuriko_alo_5","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"咦？送给我的礼物！？情人节的回礼……我、我真的会喜欢上你喔！？","en":"A White Day gift? For me?! Watch out, I might fall for you!","ja":"わ、私に贈り物ですかっ!?バレンタインの、お返し……こ、恋しちゃいますよっ!?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_6#originalText","id":"talk.vc.home_event_yuriko_alo_6","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"我绞尽脑汁想了很多愚人节的点子……但还是想不到什么有趣的谎话。","en":"I've been thinking over some possible fibs to tell for April Fools' Day... but then I got liar's block.","ja":"エイプリルフールに向けていろいろ考えてみたんですけど……面白い嘘は思いつきませんでした"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_7#originalText","id":"talk.vc.home_event_yuriko_alo_7","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"如果可以的话，黄金周我好想跟小杏一起攻略这个游戏喔～","en":"I'd sure love to spend all of Golden Week beating this game with Anna.","ja":"ゴールデンウィークはできたら杏奈ちゃんと一緒にこのゲームを攻略したいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_8#originalText","id":"talk.vc.home_event_yuriko_alo_8","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"就连在游戏里，遇到雨天也会淋湿呢。没想到这种小细节也如此逼真。","en":"It's interesting how rain in this game actually makes you wet. The sheer attention to detail is remarkable.","ja":"ゲームの中でも、雨が降ると濡れちゃうんですねそんなところもリアルなんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_9#originalText","id":"talk.vc.home_event_yuriko_alo_9","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"要是能像这样乘风飞翔，织女也可以飞越银河，和喜欢的人相聚了。","en":"If only Orihime could fly. Then she could cross the Milky Way and see Hikoboshi anytime.","ja":"こんな風に空を飛べたら、織姫も天の川を飛び越えて好きな人に会いに行けるのに"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_10#originalText","id":"talk.vc.home_event_yuriko_alo_10","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"要不要去海边集训？听说这个世界也有很美丽的海滩喔。","en":"Would you like to go camping by the sea? This world has lovely beaches.","ja":"海辺で合宿しませんか?この世界にも、キレイな浜辺があるみたいなんです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_11#originalText","id":"talk.vc.home_event_yuriko_alo_11","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"欢乐的暑假也要结束了呢。明天开始，要回归日常生活好好加油啰！","en":"Summer vacation ended too soon. But I'm excited to get back to the grind tomorrow!","ja":"楽しい夏休みも終わりですね明日からまた、いつもの生活に戻って頑張ります!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_12#originalText","id":"talk.vc.home_event_yuriko_alo_12","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"要是住在月亮上的是像小杏一样的兔子的话……肯定超级可爱。","en":"If the rabbits on the moon are anything like Anna, then they must be really cute.","ja":"月にいるのが、杏奈ちゃんみたいなウサギだったら……ものすごく可愛いですよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_13#originalText","id":"talk.vc.home_event_yuriko_alo_13","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"就算回到现实世界，如果是在万圣节期间穿这身装扮外出，应该也不会不好意思吧……？","en":"I wonder if I could dress like this for Halloween in the real world without feeling embarrassed?","ja":"現実の世界に戻ってもハロウィンの時なら、この格好で外出しても恥ずかしくないかな……?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuriko_alo_15#originalText","id":"talk.vc.home_event_yuriko_alo_15","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"这个世界的圣诞节实在好有幻想气氛……让人不禁看得出神。","en":"Christmas in this world is like something right out of a fairytale. I just find it all so enchanting.","ja":"この世界のクリスマスなんて幻想的なんだろう……思わず見入ってしまいます"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuriko_alo_1#originalText","id":"talk.vc.home_season_yuriko_alo_1","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"就算是在游戏里，也很忠实地呈现四季的变化呢。现在是春天，百花齐放！","en":"I love how the seasons are so direct in this game. Just look at all the blossoms!","ja":"ゲームの中でも、しっかり季節は変わるんですね。今は春でお花が満開です!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuriko_alo_2#originalText","id":"talk.vc.home_season_yuriko_alo_2","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"我想暑假开始后，这个游戏的上线人数也会增加吧。感觉和大家一起玩会很开心～","en":"I suppose more people will play this game in the summer. I can't wait. The more the merrier!","ja":"夏休みになったら、このゲームに来る人も増えるんでしょうね楽しそうだなあ、みんなで遊ぶのって"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuriko_alo_3#originalText","id":"talk.vc.home_season_yuriko_alo_3","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"这个世界的秋天，是不是也会让人觉得料理更加美味呢？真叫人好奇。","en":"Do you think autumn makes food taste better in this world, too? I can't wait to find out.","ja":"秋はやっぱり、この世界でもご飯がおいしくなるんでしょうか気になっちゃいますね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_yuriko_alo_4#originalText","id":"talk.vc.home_season_yuriko_alo_4","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"手好冻，而且还下雪……让人都快忘记自己是在游戏世界里呢。","en":"My hands are numb, it's snowing... It's so easy to forget this is a game.","ja":"手がかじかんで、雪が降って……なんだか、ゲームの中だってことを忘れちゃいますね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuriko_alo_1#originalText","id":"talk.vc.home_rank_yuriko_alo_1","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"恭喜升级！真不愧是你！我也不会输的！","en":"Congratulations on the rank-up! I knew you could do it! Now I've got some catching up to do.","ja":"ランクアップおめでとうございます!さすがですね! 私も負けてはいられません!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuriko_alo_2#originalText","id":"talk.vc.home_rank_yuriko_alo_2","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"已经提升到下个等级了吗？速度真快。也请教教我诀窍！","en":"You've already ranked up again? Wow, you're fast. Give me some tips!","ja":"もう次のランクなんですか?とっても早いですね私にも、コツを教えてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuriko_alo_3#originalText","id":"talk.vc.home_rank_yuriko_alo_3","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"就连在这个世界，你的等级也不断提升呢！我也想早点追上你！","en":"Wow, you're such a go-getter— even in this world! I hope I can rank up fast enough to catch up to you!","ja":"こっちの世界でも、どんどんランクアップしていきますね!私も早く追いつきたいです!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuriko_alo_4#originalText","id":"talk.vc.home_rank_yuriko_alo_4","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"你变得非常强了呢。不论在哪里，制作人先生都是我崇拜的对象！","en":"You've sure gotten strong! No matter what world you're in, I always strive to be like you, sir!","ja":"とっても強くなったんですねプロデューサーさんはどこにいてもずっと、私の憧れの人です!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_yuriko_alo_5#originalText","id":"talk.vc.home_rank_yuriko_alo_5","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"我觉得你已经称得上是最强的战士了！是真正的勇者！啊，别盯着我！小心我喜欢上你喔！？","en":"I might as well just call you the Strongest Warrior of All Time! Ah! Don't look at me or I'll fall for you!","ja":"もう最強の戦士って言っていいと思います! まさに勇者です!あ、見つめ返さないで! 恋しますよ!?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuriko_alo_1#originalText","id":"talk.vc.home_etc_yuriko_alo_1","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"完成使命，辛苦你了。建议你今天就悠闲地看本书，好好休息吧。","en":"Good work on the mission. You should take the day off. Read a book and put your feet up.","ja":"ミッションクリア、お疲れさまでした今日はゆっくり本を読んで休むのがおすすめです"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuriko_alo_2#originalText","id":"talk.vc.home_etc_yuriko_alo_2","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"有收到了要给制作人先生的礼物！……礼物总让人心暖暖的呢♪","en":"There's a present for you, sir! Don't you just love presents? They're so heartwarming♪","ja":"プロデューサーさん宛のプレゼントが届いてます! ……プレゼントって気持ちがあたたかくなりますよね♪"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuriko_alo_3#originalText","id":"talk.vc.home_etc_yuriko_alo_3","speaker":{"cn":"百合子","en":"Yuriko","ja":"百合子"},"text":{"cn":"是下一份工作吗？有遇到什么麻烦事的话，我随时都能帮忙唷！","en":"A new job came in? If you get stuck, call on me for help anytime!","ja":"次のお仕事ですか?大変なことがあれば、私がいつでもお手伝いしますからねっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_miki_alo_1#originalText","id":"talk.vc.home_wait_miki_alo_1","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"要是演唱会上也能使用魔法，肯定很有趣唷！啪啪～咚咚～地！","en":"It'd be like so much fun to use magic during our concerts, you know? We'd be like, pow! And poof!","ja":"ライブの時にも魔法が使えると楽しそうなのばばーん、どどーんって!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_miki_alo_2#originalText","id":"talk.vc.home_wait_miki_alo_2","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"这里是叫做《啊呼海姆》的游戏世界对不对？咦，不对吗？","en":"What's this game again? Elf...chime? Wait, it's not?","ja":"ここって、「あふぅへいむ」っていうゲームの中だっけ?え、違うの?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_miki_alo_3#originalText","id":"talk.vc.home_wait_miki_alo_3","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"美希的头上长出耳朵了！而且碰到还会感觉痒痒的耶！","en":"Ooh, look! Your girl's got ears! And get this, it tickles when you touch 'em!","ja":"ミキの頭に耳が生えちゃったの!しかも、触ったら、なんかちょっとくすぐったいの!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_miki_alo_4#originalText","id":"talk.vc.home_wait_miki_alo_4","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"也有人带着像宠物一样的动物呢～啊哈！美希也好想带哈姆藏来喔！","en":"Ooh, look at all the people with pets! Haha! Now I kinda wanna bring Hamuzo the hamster here!","ja":"ペットみたいな動物を連れてる人もいるんだね～あはっ、ハム蔵とか連れてきたいね!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_miki_alo_5#originalText","id":"talk.vc.home_wait_miki_alo_5","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"这个世界里有好多好多漂亮的地方喔～不论海边、山上还是天空都好美丽！","en":"Wow, this game has so, so, so many cool places to go! The beach, the sky, the mountains—it's all super pretty!","ja":"ここって、ステキな場所がたくさんたくさんあるんだね～海も山も空も、すっごくキレイ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_miki_alo_6#originalText","id":"talk.vc.home_wait_miki_alo_6","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"美希下次想跟制作人一起，两人在空中翱翔～因为在现实中没办法飞行呀。","en":"You knowww, wouldn't it be great if we went flying togetherrr? I mean, we don't get many chances to fly IRL.","ja":"ミキ、今度プロデューサーとふたりで、空を飛びたいな～だって、現実じゃ飛べないでしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_miki_alo_7#originalText","id":"talk.vc.home_wait_miki_alo_7","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"不知道可不可以没跟大家一起，而是只有我们两人单独进VR场地？可以的话就能跟你一起来了说。","en":"So, like, can't we explore this VR world with just the two of us? I'd totally come with you.","ja":"VRの場所って、みんなと一緒じゃなくて、ふたりっきりで入れない?そしたら一緒に来るのにな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_miki_alo_8#originalText","id":"talk.vc.home_wait_miki_alo_8","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"听说在这里三两下就能换好装耶！这样一来，演唱会上就能换穿好多套服装了！","en":"Hey, I hear we can change costumes all we want here! Guess who's having ten costume changes in the concert?","ja":"ここだと、簡単に衣装チェンジができちゃうんだって! それならライブでいっぱい衣装着られるね!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_miki_alo_9#originalText","id":"talk.vc.home_wait_miki_alo_9","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"怎么啦，制作人？想睡觉的话，要和美希一起睡午觉吗？","en":"What's wrong, Mr. Producer? Are you sleepy? Wanna take a nap with me?","ja":"どうしたの、プロデューサー?眠くなっちゃったならミキと一緒にお昼寝する?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_1#originalText","id":"talk.vc.home_time_miki_alo_1","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"啊呼……已经早上啦？反正还在游戏里，再让美希睡一下……晚安～","en":"*Yawn*...morning already? Well, since this is just a game... Nighty-niiight.","ja":"あふぅ……もう朝なの?ゲームの中なんだからもう少し……おやすみ～"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_2#originalText","id":"talk.vc.home_time_miki_alo_2","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"嗯～饭煮好了？那就起床吧。早餐吃什么呢～制作人？","en":"Mmm...breakfast ready? 'Kay-kay. I'll get up. So what's on the menu, Mr. Producer?","ja":"ん～ご飯できた?それじゃ、起きるね朝ご飯はなあに、プロデューサー?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_3#originalText","id":"talk.vc.home_time_miki_alo_3","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"在游戏里睡觉感觉真奇怪～这代表现实中的美希也在睡觉吗？还是醒着在玩游戏呢？","en":"It feels like, sooo weird sleeping in-game. I mean, is IRL-Miki asleep? Or is she awake, gaming?","ja":"ゲームの中で寝るって、変な感じ～これって、現実のミキも寝てるの?それとも、ゲームやって起きてるの?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_4#originalText","id":"talk.vc.home_time_miki_alo_4","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"早安，制作人！你看，今天美希准备了早餐喔！咦？已经中午了？","en":"Good morning, Mr. Producer! Your girl made breakfast, see? Huh? It's lunchtime already?","ja":"おはよプロデューサー!ほら、今日はミキが朝ご飯用意したんだよ! え、もうお昼?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_5#originalText","id":"talk.vc.home_time_miki_alo_5","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"在空中飞行，感觉会让人上瘾唷～要是在现实世界也能飞就好了～！","en":"It sure feels good to fly. A girl could get used to this, y'know? I wish we could fly for real.","ja":"空を飛ぶ感覚クセになっちゃいそうなの～向こうでも飛べたらいいのにな〜!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_6#originalText","id":"talk.vc.home_time_miki_alo_6","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"美希觉得办个空中演唱会，一定会非常有趣呢！当然粉丝们也会一起飞在空中！","en":"I think an airborne concert would be like, crazy-fun, you know? Our fans would be flying, too, of course.","ja":"空中ライブとか、すっごく楽しそうって思うな。もちろんファンのみんなも空飛んでるの!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_7#originalText","id":"talk.vc.home_time_miki_alo_7","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"这个世界有没有饭团呢～？啊哈，不知道里面会包什么料～","en":"Heyyy, d'you think this world also has onigiri? Haha! I wonder what kinda stuff they'd put inside?","ja":"この世界にもおにぎりってあるのかな～あはっ、中身は何だろうね～"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_8#originalText","id":"talk.vc.home_time_miki_alo_8","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"在夜空中飞行好像很舒服耶～啊，不过感觉有点可怕……既然如此，两个人一起飞就好了对吧！","en":"Flying at night must feel sooo good. But, it also sounds kinda scary. Oh, I know! Let's fly together!","ja":"夜の空を飛ぶのって気持ちよさそう～あ、でもちょっと怖いかも……なら、ふたりで飛べばいいんだよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_9#originalText","id":"talk.vc.home_time_miki_alo_9","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"听说这里的一天不是24小时喔～这样美希就能睡饱饱了！","en":"So, heyyy, a day isn't twenty-four hours in this world. Guess who's  sleeping in!","ja":"ここって、1日が24時間じゃないんだって～それならいっぱい寝られるね!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_10#originalText","id":"talk.vc.home_time_miki_alo_10","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"……你还醒着呀？睡不着的话，美希陪你一起睡吧！啊哈☆","en":"Oh...can't sleep? How about you snuggle up with yours truly? Haha!","ja":"……まだ起きてたの?眠れないなら、ミキが添い寝してあげるの! あはっ☆"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_11#originalText","id":"talk.vc.home_time_miki_alo_11","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"现在好～安静喔，跟现实世界的夜晚完全不同。美希觉得这样一定能睡得很安稳呢。","en":"It's like, sooo quiet here. Totally not like the real world. I'll definitely sleep well here.","ja":"すっごくしーんとしてるね向こうの夜とは全然違うのこれならぐっすり眠れるって思うな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_miki_alo_12#originalText","id":"talk.vc.home_time_miki_alo_12","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"和你聊天很开心，不过美希有点想睡了。先睡啰，晚安～","en":"As much as I'm enjoying talking, I'm kinda really sleepy now. Time for Miki's beauty sleep. 'Night!","ja":"おしゃべりはすっごく楽しいけどなんだか眠くなっちゃったのミキ先に寝るね、おやすみ～"},"kind":"dialogue"},{"uid":"talk.vc.home_day_miki_alo_1#originalText","id":"talk.vc.home_day_miki_alo_1","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"就算是星期一早上，只要能在空中飞就不会迟到了～要是这里有学校就好了。","en":"Man, why can't school just be in this world? I could fly and Mondays wouldn't be so hard.","ja":"月曜の朝でも、空を飛べれば学校に遅刻しないのにな～こっちに学校があればいいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_day_miki_alo_2#originalText","id":"talk.vc.home_day_miki_alo_2","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"明明不是假日还有这么多人上线，看来大家都很乐在游戏当中呢～","en":"It's so cool seeing everyone having so much fun on a weekday.","ja":"休みじゃないのに、たくさん遊んでる人がいるのやっぱり楽しいんだね～"},"kind":"dialogue"},{"uid":"talk.vc.home_day_miki_alo_3#originalText","id":"talk.vc.home_day_miki_alo_3","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"终于等到假日了～制作人，今天要跟美希两个人大玩特玩喔！","en":"Hello, weekend! We're gonna have lots of Miki-time, okay, Mr. Producer? ","ja":"やっとお休みだね～ミキとふたりで、いっぱい遊ぼうね、プロデューサー!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_miki_alo_4#originalText","id":"talk.vc.home_day_miki_alo_4","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"啊呼……今天不小心玩太久，好困喔……晚安～","en":"*Yawn*...I played way too hard today. Now I'm all sleepy... Nighty-niiight.","ja":"あふぅ……今日は遊び過ぎちゃったね眠くなっちゃった……おやすみ～"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_1#originalText","id":"talk.vc.home_event_miki_alo_1","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"新年快乐～希望今年也会遇到好多开心的事情！","en":"Happy New Year! I hope it's a banger!","ja":"あけましておめでとう～今年もいっぱい楽しいことがあるといいね!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_2#originalText","id":"talk.vc.home_event_miki_alo_2","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"要是能飞天撒豆，一定很好玩唷！啊，不过捡的时候可能会很辛苦～","en":"Wouldn't the Setsubun bean-toss be like, so much fun in the air?! Don't ask me to clean up, tho...","ja":"豆まきも、空を飛んでやったら楽しそうなのあ、でも拾うのが大変かな～"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_3#originalText","id":"talk.vc.home_event_miki_alo_3","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"来！这是情人节巧克力唷！里面当然包含了美希满满的心意！","en":"Here ya go! V-day chocolates! They're from the heart, of course.","ja":"はい、バレンタインのチョコなの!もちろん、ミキの気持ちがたっくさん入ってるからね!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_4#originalText","id":"talk.vc.home_event_miki_alo_4","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"每到女儿节，就让人觉得很开心呢♪草莓巴巴露亚口味的米果，就交给你准备了唷～！","en":"Hinamatsuri is so much fun! I'm expecting a box of those yummy strawberry cream cookies, okayyy?","ja":"おひな様の日って、すっごく楽しいよね♪ いちごババロア味のあられ、よろしくなの～!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_5#originalText","id":"talk.vc.home_event_miki_alo_5","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"欸～你今天是不是有什么东西要送给美希呀？","en":"Sooo, just a hunch... but do you have a present for Miki on this special day?","ja":"ねえ～、もしかして今日はミキに何かくれるものがあるんじゃない?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_6#originalText","id":"talk.vc.home_event_miki_alo_6","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"愚人节总有许多活动呢～这里会做什么呢？","en":"I'm seeing April Fool's events all over. I wonder what people do here?","ja":"エイプリルフールって色んなイベントがあるよね～ここではどんなことやるんだろう?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_7#originalText","id":"talk.vc.home_event_miki_alo_7","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"美希想在黄金周睡午觉睡得饱饱的～正好天气很温暖，感觉很舒服。","en":"This Golden Week, I wanna take ALL the naps! It's just the right weather for it.","ja":"ゴールデンウィークはたっくさんお昼寝したいな～。ちょうどあったかくて、気持ちよさそうだし"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_8#originalText","id":"talk.vc.home_event_miki_alo_8","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"梅雨季节头发总是会乱翘，所以美希很不喜欢。但是在游戏里就不会乱翘了！","en":"I used to hate rainy season 'cause it made my hair all frizzy, but that's not a problem here!","ja":"梅雨の間って、髪の毛がわしゃーってなるからイヤだったんだけどこの中はそうならないんだね!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_9#originalText","id":"talk.vc.home_event_miki_alo_9","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"你在短签上写了什么～？美希的啊～是秘密！！！","en":"Sooo, what's your Tanabata wish? You wanna know mine? Tooo bad!","ja":"短冊に何書いたの～?ミキはね～ナイショ!!!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_10#originalText","id":"talk.vc.home_event_miki_alo_10","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"在海边小屋吃的炒面真的超级好吃耶～配着饭团一起吃最棒了唷！","en":"Ever notice how yummy yakisoba tastes at the beach? Just add onigiri and you've got a perfect meal!","ja":"海の家で食べる焼きそばってすっごくおいしいよね～おにぎりと一緒に食べると最高なの!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_11#originalText","id":"talk.vc.home_event_miki_alo_11","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"暑假已经结束了吗？一泡在游戏里，就会觉得时间过得好快呢～","en":"Aw, is summer vacation over already? Gee, time sure flies in this game.","ja":"夏休み、もう終わっちゃうの?ゲームの中にいると、時間が早く感じちゃうな～"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_12#originalText","id":"talk.vc.home_event_miki_alo_12","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"赏月团子圆滚滚的好可爱唷～要吃跟年龄一样的数量对不对？","en":"Dontcha just love how cute and chubby Moon Viewing dango are? You eat your age in them, right?","ja":"お月見のお団子って丸くてかわいいよね～年の数だけ、食べるんでしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_13#originalText","id":"talk.vc.home_event_miki_alo_13","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"万圣节到了，大家都装扮得好～有趣呢！美希也好想开变装派对喔～","en":"Everyone looks soooo cool on Halloween! Aw, I wanna go to a costume party.","ja":"ハロウィンだから、み～んな面白い格好してるのミキも仮装パーティーしたいな～"},"kind":"dialogue"},{"uid":"talk.vc.home_event_miki_alo_15#originalText","id":"talk.vc.home_event_miki_alo_15","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"Merry Christmas！听说这里的圣诞节非常漂亮喔！美希想跟你一起去看！","en":"Merry Christmas! I hear this game really goes all-out for the holidays. Let's go check it out!","ja":"メリークリスマス!ここのクリスマスは、すっごくステキなんだって! 一緒に見に行きたいの!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_miki_alo_1#originalText","id":"talk.vc.home_season_miki_alo_1","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"睡午觉是很舒服的一件事，而在春天睡午觉又更、更、更舒服了。","en":"Naps are great, but springtime naps are even greater!","ja":"お昼寝はいつも気持ちいいけど春のお昼寝はもっともっと気持ちいいの"},"kind":"dialogue"},{"uid":"talk.vc.home_season_miki_alo_2#originalText","id":"talk.vc.home_season_miki_alo_2","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"美希很怕热，但在游戏中就不太会呢。可能是汗不会黏黏的关系吧。","en":"I hate the heat, but I don't mind it so much in this game. Maybe 'cause I don't get sweaty?","ja":"暑いのは苦手だけど、ゲームの中だとそうでもないかも汗がベタベタしないからかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_miki_alo_3#originalText","id":"talk.vc.home_season_miki_alo_3","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"美希不喜欢热天，但也不想要天气变冷。真希望一直都是刚刚好的温度～","en":"As much as I hate the heat, I wish it didn't have to get cold. Why can't the temperature always be just right?","ja":"暑いのもイヤだけど、寒くなるのもやめてほしいの。ずっとちょうどいい温度ならいいのにな～"},"kind":"dialogue"},{"uid":"talk.vc.home_season_miki_alo_4#originalText","id":"talk.vc.home_season_miki_alo_4","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"冬天有好多特别的活动呢！有新年、圣诞节还有情人节……全都是有好吃东西的活动唷！","en":"Winter is always full of events, huh. New Year's, Christmas, V-Day... So many yummy holidays.","ja":"冬って特別なイベントが多いよねお正月にクリスマス、バレンタイン……ぜーんぶおいしいイベントなの"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_miki_alo_1#originalText","id":"talk.vc.home_rank_miki_alo_1","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"恭喜升级唷～！下次美希会特别准备贺礼送你喔。","en":"Congrats on the rank-up! Somebody's getting a special present from Miki soon.","ja":"ランクアップおめでとなの～!今度、ミキから特別にお祝いのプレゼントあげるね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_miki_alo_2#originalText","id":"talk.vc.home_rank_miki_alo_2","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"咦？你不是不久前才升级过吗？原来你是超级努力的拼命三郎啊。","en":"Wait, didn't you like, just rank up? Wow, hardcore.","ja":"あれ、この間もランクアップしてなかった?すっごく頑張り屋さんなんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_miki_alo_3#originalText","id":"talk.vc.home_rank_miki_alo_3","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"大家都在说你变得很强，美希听到了也觉得很高兴。","en":"Everyone's talking about you. Sayin' you're really powerful now. I'm just so proud of you!","ja":"すっごく強くなったって、みんな噂してたの。なんだか、ミキもうれしくなっちゃった"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_miki_alo_4#originalText","id":"talk.vc.home_rank_miki_alo_4","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"你已经变得这么厉害啦？这样你以后也会一直守护美希啰？","en":"Whoa, can you get any stronger? You're gonna take good, good care of your Miki from now on, I hope?","ja":"こんなに強くなっちゃったの?なら、ミキのことを、ずっとずーっと守ってくれるよね?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_miki_alo_5#originalText","id":"talk.vc.home_rank_miki_alo_5","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"你真的变得好强喔！美希也不能输，一定要成为顶尖偶像！","en":"Jeez, you're like, so strong now! Looks like I've got my work cut out for me if I wanna be a top idol!","ja":"すごく強くなったんだね! ミキも負けないようにトップアイドルにならないとっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_miki_alo_1#originalText","id":"talk.vc.home_etc_miki_alo_1","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"工作结束了吧？辛苦啰～你肯定很饿对不对～？一起吃饭团吧☆","en":"Another job in the books! You must be hungry. So let's eat onigiri!","ja":"お仕事終わったんだよねお疲れさま～。お腹すいたでしょ一緒におにぎり食べよ☆"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_miki_alo_2#originalText","id":"talk.vc.home_etc_miki_alo_2","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"欸欸，听说有礼物耶！快打开看看嘛～里面是什么呢？好期待唷！","en":"Hey, you got a present! C'monnn, open it! I can't wait to see what's inside!","ja":"ねえねえ、プレゼントだって!早く開けてみようよ～何が入ってるのか、楽しみなの!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_miki_alo_3#originalText","id":"talk.vc.home_etc_miki_alo_3","speaker":{"cn":"美希","en":"Miki","ja":"美希"},"text":{"cn":"下一份工作开始了吗？真辛苦耶～下次美希也一起帮忙吧？","en":"New job came already? Always grinding, eh? Want a little help?","ja":"次のお仕事、始まったの?大変だね～。今度は、ミキが一緒に手伝ってあげようか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sylvie_1#originalText","id":"talk.vc.home_wait_sylvie_1","speaker":{"cn":"西尔薇","ja":"シルヴィー"},"text":{"cn":"人界人是害死爸爸、妈妈的人……要跟他们相亲相爱……我做不到这种事。","en":"I can't make nice with the filthy Human Empire dwellers... They killed my parents.","ja":"人界人は、父さまと母さまの仇……そんなヤツらと仲良くするなんて私にはできない"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sylvie_2#originalText","id":"talk.vc.home_wait_sylvie_2","speaker":{"cn":"西尔薇","ja":"シルヴィー"},"text":{"cn":"虽然我来到人界……但我只是为了了解人界人才来的，并不打算与他们交好。","en":"I may be in the Human Empire, but it is purely for study. Not for pleasure.","ja":"人界には来たけど……あくまで人界人について知るため馴れ合うためじゃないから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sylvie_3#originalText","id":"talk.vc.home_wait_sylvie_3","speaker":{"cn":"西尔薇","ja":"シルヴィー"},"text":{"cn":"总算能拿起剑战斗了。不过，总觉得这把剑似乎还隐藏着什么秘密……","en":"At last, I am able to wield this sword. But secrets still remain locked inside it...","ja":"やっと剣を振れるようになってきたけど、この剣、まだ隠された何かがあるような気がする……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sylvie_4#originalText","id":"talk.vc.home_wait_sylvie_4","speaker":{"cn":"西尔薇","ja":"シルヴィー"},"text":{"cn":"我不得不同意，人界确实比黑暗界还要繁荣进步，尤其是料理……","en":"I hate to admit it, but the Human Empire is more bountiful than the Dark Realm. Especially in food.","ja":"人界は、暗黒界より栄えているそれは認めないといけない特に、料理は……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sylvie_5#originalText","id":"talk.vc.home_wait_sylvie_5","speaker":{"cn":"西尔薇","ja":"シルヴィー"},"text":{"cn":"夏莉为什么能够原谅人界人？他们明明是莉琵雅大人的敌人。","en":"How was Shirley able to forgive the Human Empire for what they did to Lady Lipia?","ja":"シャーリーは、どうして人界人を許すことができたのリピア様の敵なのに"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sylvie_6#originalText","id":"talk.vc.home_wait_sylvie_6","speaker":{"cn":"西尔薇","ja":"シルヴィー"},"text":{"cn":"我不愿相信我们能和人界人和平共存……但如果发生战争，又会有人不幸牺牲。","en":"I won't believe in peace with the Human Empire...but if there's another war, innocents will die.","ja":"人界人との平和なんて信じたくはないけど……戦争になれば、また犠牲者が出てしまう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sylvie_7#originalText","id":"talk.vc.home_wait_sylvie_7","speaker":{"cn":"西尔薇","ja":"シルヴィー"},"text":{"cn":"我会从你身上偷走所有剑技和术式，你做好觉悟吧！","en":"I shall steal every sword skill and Art from you! Say your prayers.","ja":"お前からは、すべての剣技や術式を盗んでやる覚悟しておくんだな!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sylvie_8#originalText","id":"talk.vc.home_wait_sylvie_8","speaker":{"cn":"西尔薇","ja":"シルヴィー"},"text":{"cn":"在黑暗界也从没出现过使用两把剑的骑士……但不知为何，看起来好像很利于战斗的样子。","en":"Not even in my realm was there a dual-wielder... However, he still seems like an easy opponent.","ja":"2本の剣を操る騎士は、暗黒界にもいなかった……でも、なぜかとても戦いやすそうに見えるな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sylvie_9#originalText","id":"talk.vc.home_wait_sylvie_9","speaker":{"cn":"西尔薇","ja":"シルヴィー"},"text":{"cn":"人界真是个和平的地方，和平到……无趣的地步。","en":"The Human Empire is quite peaceful. So peaceful... and I'm bored to tears.","ja":"人界は平和なところだな平和すぎて……退屈なくらい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sylvie_1#originalText","id":"talk.vc.home_touch_sylvie_1","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"这个发饰是妈妈给我的，别随便乱摸它！","en":"I got this hairpin from Mother. Keep your grubby hands off it!","ja":"この髪飾りは、母さまからもらったものだ気安く触るな!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sylvie_2#originalText","id":"talk.vc.home_touch_sylvie_2","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"你、你想做什么！我没理由让你摸头发！","en":"Wh-What are you doing?! You have no excuse for touching my hair!","ja":"な、なんのつもりだ!お前に髪を触られる理由なんて私にはないっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sylvie_3#originalText","id":"talk.vc.home_touch_sylvie_3","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"……你不管对谁都会这样又碰又摸的吗？稍微有点分寸好不好？","en":"Do you just...go around touching everyone? Could you show a little restraint?","ja":"……お前は、誰にでもそうして触ったり撫でたりしているの?少しはわきまえたらどう?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sylvie_1#originalText","id":"talk.vc.home_time_sylvie_1","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"早安，妈妈……──！！！快、快忘了我刚才说的！听见了吗！？","en":"Good morning, Moth...er?! F-Forget what I just said! Got it?!","ja":"おはよう、母さま……――っ!!!い、今のは忘れろ! いいな!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sylvie_2#originalText","id":"talk.vc.home_time_sylvie_2","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"你也赖床赖太久了吧？你这样真的是人界最强的男性吗？","en":"My, what a lazy oaf you are. And you call yourself the strongest person in the Human Empire?","ja":"ずいぶん朝寝坊なんだなそれで、本当に人界で一番強い男なのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sylvie_4#originalText","id":"talk.vc.home_time_sylvie_4","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"只有料理这件事我不得不认同人界……还是说，是圣堂比较特别？","en":"I must admit, Human Empire cuisine can't be beat... Unless food in the Cathedral is special somehow?","ja":"料理の出来だけは、人界を認めざるを得ないな……それとも、カセドラルが特別なのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sylvie_5#originalText","id":"talk.vc.home_time_sylvie_5","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"干净的水、茂密的森林……要是黑暗界也有这些，就会过得更富足了。","en":"Clear waters and lush forests... If only the Dark Realm were like this. Then it would be more prosperous.","ja":"綺麗な水に、生い茂る森……これが暗黒界にもあればもっと豊かになるのに"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sylvie_7#originalText","id":"talk.vc.home_time_sylvie_7","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"我今天也学了一大堆人界人骗人的花样喔，很快就能超越你了。","en":"I stole many Human Empire tricks today. Just a bit more training, and I shall be better than you.","ja":"今日も、人界人の手管をたくさん盗めたぞお前を超えるのも、あと少しだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sylvie_8#originalText","id":"talk.vc.home_time_sylvie_8","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"原来在人界和黑暗界看到的月亮是一样的啊。那么，为什么人界和黑暗界会有这么大的不同……？","en":"The moon is the same in both lands. So why is it that the Human Empire and Dark Realm are so different?","ja":"月は人界も暗黒界も同じなんだななら、どうして人界と暗黒界はあんなにも違うんだろう……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sylvie_10#originalText","id":"talk.vc.home_time_sylvie_10","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"我梦到爸爸和妈妈了。他们抛下我，去了很远的地方，是个很悲伤的梦……","en":"I dreamed about Mother and Father. They left me...and disappeared far, far away... What a sad dream.","ja":"父さまと母さまの夢を見たんだ私を置いて、遠くに行ってしまう、悲しい夢を……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sylvie_11#originalText","id":"talk.vc.home_time_sylvie_11","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"……我只是有点睡不着。你不用担心我，快走开啦。","en":"I'm just having a hard time sleeping. You needn't concern yourself. Begone at once.","ja":"……少し眠れないだけだお前が気にする必要はないさっさと向こうへ行け"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sylvie_1#originalText","id":"talk.vc.home_day_sylvie_1","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"安息日早就结束了，你怎么还一脸松懈啊？","en":"The day of rest is long gone. Why the relaxed smile?","ja":"安息日はとっくに終わっているのになんだその緩んだ顔は?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sylvie_2#originalText","id":"talk.vc.home_day_sylvie_2","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"我能做的只有每天锻炼自己。我得这么做，才能为爸爸和妈妈雪恨。","en":"I live to strengthen myself every day. I must do so to avenge my mother and father.","ja":"毎日、己を鍛えるのみそうじゃなければ、父さまと母さまの無念を晴らすことはできないんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sylvie_3#originalText","id":"talk.vc.home_day_sylvie_3","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"就算是安息日，我也不会休息喔。因为我要趁你们休息的时候追过你们！","en":"I will not rest, even on a day of rest. While you lot are resting, I'll be besting you!","ja":"安息日だって、私は休まないぞお前たちが休んでいる間に追い抜いてやるんだから!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sylvie_4#originalText","id":"talk.vc.home_day_sylvie_4","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"感觉真的有点累了……今天就好好休息，明天再……加油……","en":"I suppose I did exhaust myself a little... I will rest up tonight and start again...tomorrow...","ja":"さすがに、少し疲れたかも……今日はしっかり休んでまた、明日……から……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sylvie_1#originalText","id":"talk.vc.home_event_sylvie_1","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"又到了新的一年。我今年一定要替爸爸和妈妈报仇！","en":"A new year is upon us. I swear that this will be the year I avenge you, Mother, Father!","ja":"新しい年になってしまった今年こそ、必ず父さまと母さまの仇を取ってやる!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sylvie_3#originalText","id":"talk.vc.home_event_sylvie_3","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"凭什么我得给你点心才行？这是要给亚丝娜的。","en":"Why do you assume these sweets are for you? These are for Asuna.","ja":"なぜ私がお前に菓子をやらねばならないこれはアスナにあげるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sylvie_8#originalText","id":"talk.vc.home_event_sylvie_8","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"一下雨我就会很开心。能够尽情喝淡水，这可是极致奢侈的享受喔！","en":"Rain always makes me so happy. Drinking fresh rainwater is the height of luxury!","ja":"雨が降ると嬉しくなるんだ真水がたっぷり飲めるのは最高の贅沢なんだぞ!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sylvie_9#originalText","id":"talk.vc.home_event_sylvie_9","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"只要能见到自己珍爱的人，就算一年只能见一次面也没关系。","en":"If I got to see the ones I loved most, even just one day per year would suffice.","ja":"大事な人に会えるならたとえ一年に一度しか会えなくてもいいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sylvie_10#originalText","id":"talk.vc.home_event_sylvie_10","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"竟然有这么多干净的水，多到整个人都能没入水里……真想让爸爸、妈妈也玩玩水啊。","en":"My goodness...clean water as high as my own head... I wish my parents could have bathed in this manner.","ja":"頭まで潜れるくらいキレイな水があるなんて……父さまと母さまにも水浴びさせてあげたかったな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sylvie_12#originalText","id":"talk.vc.home_event_sylvie_12","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"我还想说今天怎么到了晚上都还很适合练习，原来是出了这么大的月亮啊。","en":"I had thought tonight would be a good time to train, but the moon is so huge.","ja":"今日は夜でも稽古がしやすいと思ったら、こんなに大きな月が出ていたのか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sylvie_13#originalText","id":"talk.vc.home_event_sylvie_13","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"我知道了，透过打扮成强大的魔物，将魔物的力量化为己有，就是这样的咒术对不对？","en":"Understood. So, I am supposed to dress as a monster so that I may harness its powers, yes?","ja":"わかったぞ、強い魔物の格好をしてその力を自分のものにしようっていうまじないだな?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sylvie_15#originalText","id":"talk.vc.home_event_sylvie_15","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"有这么多好料，真像做梦一样。要是有一天黑暗界的孩子们也能享受这种大餐就好了。","en":"This feast is a dream come true. I hope that someday children of the Dark Realm might eat like this.","ja":"こんなご馳走、夢みたいだいつか、暗黒界の子どもたちも食べられるようになるといいな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sylvie_1#originalText","id":"talk.vc.home_season_sylvie_1","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"原来春天会开这么多花啊……我都不知道……","en":"Does springtime always have this many flowers? I had no idea...","ja":"春って、こんなにたくさんの花が咲くものなのか……知らなかったな……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sylvie_2#originalText","id":"talk.vc.home_season_sylvie_2","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"因为你老是穿得黑漆漆的才会热，脱下来不就会凉一点了吗？","en":"Dressing in black is the reason you're overheated. Drop a layer or two and perhaps you'll feel better?","ja":"そんな、黒ばっかりの格好をしているから暑いんだ脱げば少しは涼しいんじゃないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sylvie_3#originalText","id":"talk.vc.home_season_sylvie_3","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"亚丝娜做的菜的确很好吃，但还是比不上妈妈做的料理。","en":"Asuna's cooking is indeed delicious. But Mother's fare was far superior.","ja":"アスナの料理は、確かにおいしいでも、母さまが作ってくれた料理には及ばないけどな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_sylvie_4#originalText","id":"talk.vc.home_season_sylvie_4","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"虽然今天很冷，但人界的房子很温暖，所以穿得少一点也没问题，锻炼起来也非常顺利！","en":"The weather is cold out, but Human Empire buildings are warm enough to dress light. Ideal for training!","ja":"今日は寒いけど、人界の建物は暖かいから、薄着でも大丈夫だ鍛錬もはかどるな!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sylvie_3#originalText","id":"talk.vc.home_bd_sylvie_3","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"今天是桐人的生日……哼，我才不会帮他庆祝。","en":"Kirito's birthday... Humph. I'm not giving him anything.","ja":"キリトの誕生日……ふん、祝ってなんかやらないぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_sylvie_6#originalText","id":"talk.vc.home_bd_sylvie_6","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"今天是亚丝娜的生日啊……她总是请我吃饭，我就稍微帮她庆祝一下好了……","en":"Asuna's birthday... Perhaps I should give her a little present, to thank her for all those meals.","ja":"アスナの誕生日か……いつもご飯を食べさせてもらってるから、少しはお祝いしようかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sylvie_1#originalText","id":"talk.vc.home_rank_sylvie_1","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"你似乎成长了一些。不过，你应该不会满足于这种程度吧？","en":"You've grown a little, I see. But I hope you aren't satisfied where you're at.","ja":"少しは成長したみたいだなでも、その程度で満足なんてしないだろうな?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sylvie_2#originalText","id":"talk.vc.home_rank_sylvie_2","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"哦～不知不觉间你也变得挺强的嘛，跟我过招看看吧。","en":"Hmmm... You've bulked up quite a bit in my absence. Let's spar a little.","ja":"ふーん、いつの間にかずいぶん力をつけたみたいじゃないか少し手合わせしてみよう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sylvie_3#originalText","id":"talk.vc.home_rank_sylvie_3","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"你平时的锻炼似乎展现出成果了，很了不起喔。","en":"Your daily training has paid off, I see. I'm rather impressed.","ja":"日頃の鍛錬の成果が現れたみたいだななかなか立派だぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sylvie_4#originalText","id":"talk.vc.home_rank_sylvie_4","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"唔，你怎么变得这么强？我也不能再浑浑噩噩的了……好，你陪我特训！","en":"Agh! How did you get so strong? I mustn't be complacent... Yes, allow me to train with you!","ja":"くっ、なぜそんなに強くなったんだ?私もうかうかしていられないな……よし、特訓に付き合ってくれ!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_sylvie_5#originalText","id":"talk.vc.home_rank_sylvie_5","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"可恶，我大概赢不过你了。但是只要你一大意，我就会立刻追上你，做好觉悟吧！","en":"I am no longer a match for you. But don't get cocky—I will catch up to you before you realize it!","ja":"もう、私じゃ勝てないかもなでも、油断してたら私がすぐに追いつくから、覚悟しておくんだぞ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sylvie_1#originalText","id":"talk.vc.home_etc_sylvie_1","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"达成使命了吗？手脚还挺快的嘛，不愧是我看好的对手！","en":"Did you complete a mission? My, that was fast. I knew you were a worthy rival!","ja":"使命を達成したのか?ずいぶん早いんだなさすが、私が見込んだ相手だ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sylvie_2#originalText","id":"talk.vc.home_etc_sylvie_2","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"你不是收到礼物了吗？要马上确认喔，不然放到坏掉就太浪费了。","en":"Well, you've got a present. You should check it immediately. You wouldn't want it to rot.","ja":"贈り物がきているじゃないかすぐに確認するんだぞ腐ったらもったいない"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sylvie_3#originalText","id":"talk.vc.home_etc_sylvie_3","speaker":{"cn":"西尔薇","en":"Sylvie","ja":"シルヴィー"},"text":{"cn":"下个使命已经确定了是吧。好了，再不赶紧准备，可是会晚别人一步喔！","en":"The next mission has arrived. Come, we must prepare to depart at once!","ja":"次の使命が決まったなほら、すぐに準備をしないと出遅れてしまうぞ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alphen_1#originalText","id":"talk.vc.home_wait_alphen_1","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"大家肯定很担心，我们得尽早回去才行。","en":"Everyone must be worried about us, so we want to get home as soon as possible.","ja":"みんな心配しているだろうからできるだけ早く帰らないとな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alphen_2#originalText","id":"talk.vc.home_wait_alphen_2","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"要是我独自一人，我一定会束手无策。虽然这么说有些难为情，但希侬妳能待在我身边，真的太好了。","en":"I would have gone mad with worry if I were alone. I blush saying this, but I'm glad you're with me, Shionne.","ja":"きっと俺ひとりだったら、途方に暮れていたと思う。何だか照れくさいけどシオンがいてくれてよかったよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alphen_3#originalText","id":"talk.vc.home_wait_alphen_3","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"看来这里的领将和我们世界里的不一样，立场似乎比较像是领袖……","en":"The lords here are different from the ones in our world. I suppose they're more like leaders?","ja":"ここの領将は、俺たちの世界とは違うんだな。リーダーのような立場なんだろうか……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alphen_4#originalText","id":"talk.vc.home_wait_alphen_4","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"桐人的每一招剑技都很厉害，我想战斗时一定派得上用场。","en":"Each and every one of Kirito's sword moves are exemplary. Everything would serve us well in battle.","ja":"キリトの剣技はどれも見事だきっと戦闘でも役に立つと思う"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alphen_5#originalText","id":"talk.vc.home_wait_alphen_5","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"看着桐人，我就会想起洛。两人的战斗方式虽不同，但身形和声音像是同一个模子印出来的。","en":"Kirito reminds me a little of Law. Their fighting styles may differ, but their voices are identical.","ja":"キリトを見ていると、ロウを思い出すな。戦い方は違うが姿も声もそっくりだからな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alphen_6#originalText","id":"talk.vc.home_wait_alphen_6","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"桐人给我的三明治带着刺激性的辣味，非常好吃。希侬妳要不要也来一个？","en":"Kirito's sandwiches were so tasty they gave me a shock. Would you like to try some, Shionne?","ja":"キリトがくれたサンドイッチ刺激的ですごくおいしいんだシオンもどうだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alphen_7#originalText","id":"talk.vc.home_wait_alphen_7","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"这里的每一位居民看起来都很快乐，这景象真美好。","en":"Everyone who lives here seems so happy. What a lovely sight.","ja":"ここの住人は、みんな楽しそうで良い光景だな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alphen_8#originalText","id":"talk.vc.home_wait_alphen_8","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"话说回来，女性战士还真多，是这个世界的特色吗……还是只有桐人身边是这样？","en":"I've never seen so many lady fighters. Maybe it's a feature of this world...or is it just Kirito?","ja":"それにしても、女性の戦士が多いなこの世界の特徴なのか……それともキリトの周りだけなのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alphen_9#originalText","id":"talk.vc.home_wait_alphen_9","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"累了的话，要不要休息一下？我听说有不错的店家喔。","en":"Would you like to have a rest? They told me of a nice eatery.","ja":"疲れたなら、休憩にしないか?いい店を教えてもらったんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alphen_1#originalText","id":"talk.vc.home_time_alphen_1","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"早安……感觉床铺太软了，我睡得不太好呢。","en":"Good morning... I couldn't sleep very well. The bed was too soft.","ja":"おはよう……なんだか寝床が柔らかすぎてうまく寝付けなかったよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alphen_4#originalText","id":"talk.vc.home_time_alphen_4","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"真没想到在这边的世界也得和领将战斗……","en":"I never imagined I'd have to fight corrupt lords in this world, too.","ja":"まさか、こっちの世界でも領将と戦うなんて思ってなかったな……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alphen_7#originalText","id":"talk.vc.home_time_alphen_7","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"在这边吃到的晚餐是不赖……但我有点怀念大家围着篝火一起用餐的时光。","en":"Suppers in this world are quite tasty, but I really do miss eating around an open fire.","ja":"ここで食べる夕食はうまいけど……たき火を囲んでみんなで食べた食事が、ちょっと懐かしくなるな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alphen_8#originalText","id":"talk.vc.home_time_alphen_8","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"全是些我没见过的武器呢……究竟是用什么做成的？","en":"All of these weapons are completely foreign to me. What are they made of?","ja":"初めて目にする武器ばかりだな……一体何で出来てるんだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alphen_9#originalText","id":"talk.vc.home_time_alphen_9","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"总觉得桐人跟洛很像呢，但他们个性完全不一样……大概是给人的感觉很相似吧。","en":"Kirito does resemble Law. Though their personalities are completely different...their auras, too.","ja":"キリトは、どこかロウに似ている気がするな。性格は全く違うが……雰囲気かもな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alphen_10#originalText","id":"talk.vc.home_time_alphen_10","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"睡不着吗？……放心，我们一定回得去的，一起努力到那个时候吧。","en":"Can't sleep? Fear not, we'll return home someday. Let's both do our best to ensure that day comes soon.","ja":"眠れないのか?……大丈夫、必ず帰れるさその時まで、一緒に頑張ろう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alphen_1#originalText","id":"talk.vc.home_rank_alphen_1","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"希侬一旦看准目标就不会失手呢。看来我也有必要多向妳学习怎么提升精准度。","en":"You never miss a target, do you, Shionne? I could learn from your precision.","ja":"シオンは狙ったら外さないな俺もその正確さは見習う必要がありそうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alphen_2#originalText","id":"talk.vc.home_rank_alphen_2","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"这下距离打倒领将又更近一步了。","en":"Now we're one step closer to defeating the lords.","ja":"これでまた一歩、打倒領将に近づいたな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alphen_3#originalText","id":"talk.vc.home_rank_alphen_3","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"不能老是依赖希侬妳，我得让自己变强，强到能保护妳才行……","en":"You're always rescuing me, Shionne. That won't do. I must get stronger so that I can return the favor.","ja":"シオンに頼ってばかりじゃいられないよな。俺がシオンを守れるようにならないと……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alphen_4#originalText","id":"talk.vc.home_rank_alphen_4","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"妳变得这么强，回去后一定会让洛和琳薇尔大吃一惊的。","en":"Law and Rinwell will certainly be surprised when we return much stronger than before.","ja":"こんなに強くなって帰ったらロウもリンウェルも、きっとビックリするだろうな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alphen_5#originalText","id":"talk.vc.home_rank_alphen_5","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"现在的希侬一定能够达成目标的。一起加油吧。","en":"I know you can reach every target you set your sights on, Shionne. Let's do this together.","ja":"今のシオンなら、きっと目的を果たすことができる一緒に頑張ろう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alphen_1#originalText","id":"talk.vc.home_etc_alphen_1","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"恭喜妳达成目标，我就相信妳一定办得到的。","en":"Congratulations on reaching your goal. I always believed in you.","ja":"目標達成、おめでとう君ならできるって信じてたよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alphen_2#originalText","id":"talk.vc.home_etc_alphen_2","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"似乎有人送礼物来了。如果里头是武器，可以让我看看吗？","en":"A present seems to have arrived. If it's a weapon, will you show it to me?","ja":"誰かからの贈り物が来てるみたいだな武器だったら、ちょっと見せてくれないか"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alphen_3#originalText","id":"talk.vc.home_etc_alphen_3","speaker":{"cn":"奥尔芬","en":"Alphen","ja":"アルフェン"},"text":{"cn":"看来妳已经决定好下个目的地了。好，准备好之后就赶紧出发吧！","en":"Our next mission has arrived. Let's get ready to depart at once!","ja":"次の目的地が決まったんだなよし、準備ができたらさっそく出発しよう!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shionne_1#originalText","id":"talk.vc.home_wait_shionne_1","speaker":{"cn":"希侬","ja":"シオン"},"text":{"cn":"这世界的人们既和善亲切，又爱照顾人，就跟某人一模一样呢。","en":"People-pleaser this, mother hen that. The people of this world all remind me of a certain someone.","ja":"お人よしで、世話焼きだなんてこの世界の人たちもまるで誰かさんのようね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shionne_2#originalText","id":"talk.vc.home_wait_shionne_2","speaker":{"cn":"希侬","ja":"シオン"},"text":{"cn":"我们还有事要做，得快点回去才行。","en":"We have a mission we must accomplish. And we must return home quickly.","ja":"私たちにはやることがあるのだから早く戻らないといけないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shionne_3#originalText","id":"talk.vc.home_wait_shionne_3","speaker":{"cn":"希侬","ja":"シオン"},"text":{"cn":"在空中飞行是怎样的感觉呢？我有点感兴趣。","en":"I wonder what flight feels like. I must admit I am a little curious.","ja":"空を飛ぶ、というのはどんな気持ちなのかしら少し興味があるわね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shionne_4#originalText","id":"talk.vc.home_wait_shionne_4","speaker":{"cn":"希侬","ja":"シオン"},"text":{"cn":"那个叫亚丝娜的人好会做菜喔，完全不输奇莎兰呢。","en":"That Asuna girl is quite the accomplished cook. As good as Kisara, even.","ja":"あのアスナという人、かなり料理が上手ねキサラにも負けていないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shionne_5#originalText","id":"talk.vc.home_wait_shionne_5","speaker":{"cn":"希侬","ja":"シオン"},"text":{"cn":"我真的好久没这样停留在同一个地方悠闲度过了……","en":"It truly has been ages since I've settled in one spot for a while.","ja":"こうして同じ場所に留まってゆっくりするのは本当に久しぶりだわ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shionne_6#originalText","id":"talk.vc.home_wait_shionne_6","speaker":{"cn":"希侬","ja":"シオン"},"text":{"cn":"我的〈荆棘〉和你的痛觉都维持着原状，感觉好奇妙。","en":"It seems my thorn curse and your sense of pain have returned to normal. What a strange feeling.","ja":"私の〈荊〉も、あなたの痛覚も元のままなのねなんだか、妙な気分だわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shionne_7#originalText","id":"talk.vc.home_wait_shionne_7","speaker":{"cn":"希侬","ja":"シオン"},"text":{"cn":"这里不只有妖精，大家还能在天上飞，就像是琳薇尔说过的童话世界呢。","en":"Fairies, people flying to and fro— reminds me of Rinwell's stories.","ja":"妖精がいたり、みんな空を飛んだりリンウェルが話していたおとぎ話の世界みたいね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shionne_8#originalText","id":"talk.vc.home_wait_shionne_8","speaker":{"cn":"希侬","ja":"シオン"},"text":{"cn":"在这里也能使用星灵术啊……真是不可思议。","en":"Even here, I can still use Astral Artes... What a curious feeling.","ja":"ここでも星霊術は使えるのね……不思議な感じだわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shionne_9#originalText","id":"talk.vc.home_wait_shionne_9","speaker":{"cn":"希侬","ja":"シオン"},"text":{"cn":"怎么了，在那边发呆？身体不舒服的话，你可要早点说。","en":"What's wrong? Your head is in the clouds. If you're feeling ill, please say so.","ja":"どうしたの、ぼーっとして体調が悪いなら、早めに言いなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shionne_1#originalText","id":"talk.vc.home_time_shionne_1","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"好了，快起床。人家已经帮我们做好早餐了，还让人等就太不礼貌了。","en":"Come on, out of bed. It's rude to keep someone waiting when they've made breakfast for you.","ja":"ほら、起きなさい朝食を作ってくれてるんだから待たせたら失礼でしょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shionne_4#originalText","id":"talk.vc.home_time_shionne_4","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"水、土、风、热、光、暗……这个世界很平衡呢。","en":"Water and earth, wind and fire, light and dark... this world is quite balanced.","ja":"水も土も風も熱も、光と闇も……この世界は均衡を保っているのね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shionne_7#originalText","id":"talk.vc.home_time_shionne_7","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"我上次放松泡澡都不知是何时的事了……得好好感谢亚丝娜才行。","en":"How long has it been since I had a soothing soak in the bath? I must thank Asuna later.","ja":"のんびりお風呂に入ったのはいつ以来かしら……アスナに感謝しないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shionne_8#originalText","id":"talk.vc.home_time_shionne_8","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"刚才看到的食物是什么？我、我没有很在意啦……","en":"What was that food I saw earlier? N-Not that I'm curious about it...","ja":"さっき見かけた食べ物は何かしら?べ、別に気になっているわけじゃ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shionne_9#originalText","id":"talk.vc.home_time_shionne_9","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"这套服装怎么样？某人默默地两眼盯着不放呢。","en":"Is there something wrong with my clothing? Somebody was staring an awful lot at me.","ja":"この衣装はどうかしら?誰かさんは無言でジロジロ見てきたけれど"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shionne_10#originalText","id":"talk.vc.home_time_shionne_10","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"误闯到这里来的时候，我还以为再也回不去了……不，没事，别在意。","en":"When we first got lost here, I thought we would be stuck forever... It's nothing. Forget I said that.","ja":"ここに迷い込んだ時もう戻れないのかと思ったの……いえ、なんでもないわ。気にしないで"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_shionne_1#originalText","id":"talk.vc.home_rank_shionne_1","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"你似乎多少学会如何使剑了。照着这个步调，继续精进剑技吧。","en":"It seems you've learned how to use the swords here. Keep at it and improve your technique.","ja":"少しは剣の使い方を覚えたようねその調子で、もっと腕を磨きなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_shionne_2#originalText","id":"talk.vc.home_rank_shionne_2","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"你的攻击越来越精准了，是因为学会怎么观察敌人的动作了吗？","en":"You've been hitting your targets well. Perhaps you've learned to read enemy movements?","ja":"狙いが正確になってきたわね敵の動きを観察することを覚えたのかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_shionne_3#originalText","id":"talk.vc.home_rank_shionne_3","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"为了跟领将战斗，你有充分训练自己呢。我稍微对你刮目相看了。","en":"I see you've been training hard for our fight with the lords. Perhaps I underestimated you.","ja":"領将との戦いに備えてちゃんと訓練してるのね少しだけ、見直したわ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_shionne_4#originalText","id":"talk.vc.home_rank_shionne_4","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"你的强大，肯定是源自于你想保护人的心意吧。","en":"I am certain your strength comes from your drive to protect others.","ja":"あなたの強さはきっと、人を守りたいっていう気持ちから来ているのね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_shionne_5#originalText","id":"talk.vc.home_rank_shionne_5","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"相信我们一定能够打倒所有领将。我很信任你喔。","en":"I am confident that together, you and I can defeat all the evil lords. I'm counting on you.","ja":"きっと私達なら、全ての領将を倒すことができる頼りにしてるわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_shionne_1#originalText","id":"talk.vc.home_etc_shionne_1","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"达成目标了。所谓的个性，不论在哪个世界都是不会变的呢。","en":"Mission accomplished. No matter what world you're in, your nature stays the same, doesn't it?","ja":"目標達成よどの世界にいても、性格というのは変わらないものね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_shionne_2#originalText","id":"talk.vc.home_etc_shionne_2","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"我想那是给你的礼物。感觉快点确认内容会比较好喔。","en":"There's a gift addressed to you. I think you should open it as soon as possible.","ja":"あなた宛ての贈り物だと思うわ中身を早く確認した方が良さそうね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_shionne_3#originalText","id":"talk.vc.home_etc_shionne_3","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"cn":"我知道下个目的地了。来，立刻出发吧。","en":"Our next orders have arrived. Let's head out immediately.","ja":"次の目的地がわかったわさあ、すぐに向かいましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_real_junior_high_school_1#originalText","id":"talk.vc.home_wait_mito_real_junior_high_school_1","speaker":{"cn":"深澄","ja":"深澄"},"text":{"cn":"你来了啊，太好了……","en":"Oh, good. You're here.","ja":"来てくれたのねよかった……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_real_junior_high_school_2#originalText","id":"talk.vc.home_wait_mito_real_junior_high_school_2","speaker":{"cn":"深澄","ja":"深澄"},"text":{"cn":"如果在VR当中也能跟妳在一起，那肯定会很开心吧。","en":"If I have to be in VR, I know it would be a lot of fun as long as I was with you.","ja":"VRの中でも、貴方と一緒だったらきっとすごく楽しいだろうな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_real_junior_high_school_3#originalText","id":"talk.vc.home_wait_mito_real_junior_high_school_3","speaker":{"cn":"深澄","ja":"深澄"},"text":{"cn":"希望在正式营运能见到封闭测试时遇到的那名黑色剑士。他绝对也有玩。","en":"I hope I get to see that black swordsman from the beta test after launch. He must still be playing.","ja":"ベータテストで見た、あの黒い剣士正式サービスで会えるといいな絶対、やってるはずだし"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_real_junior_high_school_4#originalText","id":"talk.vc.home_wait_mito_real_junior_high_school_4","speaker":{"cn":"深澄","ja":"深澄"},"text":{"cn":"虽然妳跟我完全不一样……但或许正因为如此，我们才能这么要好。","en":"You and I are completely different... Maybe that's why we get along so well.","ja":"貴方と私は、全然違うけど……だからこそ、仲良くなれるのかもね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_real_junior_high_school_5#originalText","id":"talk.vc.home_wait_mito_real_junior_high_school_5","speaker":{"cn":"深澄","ja":"深澄"},"text":{"cn":"难道只有我知道妳欢欣雀跃时的表情？……呵呵，这样感觉还不错。","en":"Am I perhaps the only person who has seen you at your giddiest? Haha...I don't think I mind that.","ja":"貴方のはしゃいだ顔を知ってるのはもしかしたら私だけ？……ふふ、それってちょっといいかも"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_real_junior_high_school_6#originalText","id":"talk.vc.home_wait_mito_real_junior_high_school_6","speaker":{"cn":"深澄","ja":"深澄"},"text":{"cn":"没事吧？你看起来一脸疲惫。","en":"You okay? You look tired.","ja":"大丈夫?疲れた顔よ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_real_junior_high_school_7#originalText","id":"talk.vc.home_wait_mito_real_junior_high_school_7","speaker":{"cn":"深澄","ja":"深澄"},"text":{"cn":"动手指玩游戏也会对大脑有正面影响喔……我乱讲的，妳相信了？","en":"Moving your fingers in-game is supposed to be good for the brain... Not! Did you really believe that?","ja":"ゲームで指を動かすのは脳にもいい影響があるのよ……なんて、信じた？"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_real_junior_high_school_8#originalText","id":"talk.vc.home_wait_mito_real_junior_high_school_8","speaker":{"cn":"深澄","ja":"深澄"},"text":{"cn":"小心，不要误判撤退时机。这才是最重要的。","en":"Don't quit prematurely. That's the most important thing to remember.","ja":"退きどきを見誤らないようにねそれが一番大事"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mito_real_junior_high_school_9#originalText","id":"talk.vc.home_wait_mito_real_junior_high_school_9","speaker":{"cn":"深澄","ja":"深澄"},"text":{"cn":"要不要再聊一下？我找到一家好吃的店。","en":"Wanna hang out a bit more? I know this great restaurant.","ja":"もう少し話をしない?美味しいお店を見つけたから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_real_junior_high_school_1#originalText","id":"talk.vc.home_touch_mito_real_junior_high_school_1","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"想要我帮你弄头发？那你去坐在那边。","en":"You want me to touch your hair? Then sit down.","ja":"髪をいじって欲しいの?そこに座って"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_real_junior_high_school_2#originalText","id":"talk.vc.home_touch_mito_real_junior_high_school_2","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"唉唷……怎样啦……","en":"Jeez... What?","ja":"もう……何……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_real_junior_high_school_3#originalText","id":"talk.vc.home_touch_mito_real_junior_high_school_3","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"有种怪怪的感觉……","en":"This feels...weird.","ja":"何だか、変な感じ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_real_junior_high_school_4#originalText","id":"talk.vc.home_touch_mito_real_junior_high_school_4","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"喂……！","en":"Hey, pal...!","ja":"ちょっと……!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_real_junior_high_school_5#originalText","id":"talk.vc.home_touch_mito_real_junior_high_school_5","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"这里的制服还算可爱呢。","en":"The uniforms here are kind of cute, I guess.","ja":"ここの制服は、まあまあかわいいわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_real_junior_high_school_6#originalText","id":"talk.vc.home_touch_mito_real_junior_high_school_6","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"又这样撒娇……","en":"Again with the puppy dog eyes...","ja":"また、そんなおねだりして……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_real_junior_high_school_7#originalText","id":"talk.vc.home_touch_mito_real_junior_high_school_7","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"真是的！我看起来像是会让人撒娇的类型吗！？","en":"Hey! Do I look like the affectionate type?!","ja":"もうっ!私が、甘えられるようなタイプに見える!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_mito_real_junior_high_school_8#originalText","id":"talk.vc.home_touch_mito_real_junior_high_school_8","speaker":{"cn":"深澄","en":"Misumi","ja":"深澄"},"text":{"cn":"我现在正好在玩游戏，可以晚一点再说吗？再一下就结束了。","en":"We're in-game right now— could you save that for later? I'm almost done.","ja":"今はちょっとゲーム中だからあとにしてくれる？もう少しで終わるから"},"kind":"dialogue"}]};
